Here's your Snake game:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Snake</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a0a;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:monospace;color:#0f0}
canvas{border:2px solid #0f0;background:#111}
#ui{margin-top:12px;font-size:14px;display:flex;gap:20px}
#gameover{display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#000;border:2px solid #0f0;padding:30px;text-align:center}
#gameover h2{color:#f00;margin-bottom:10px}
#gameover button{background:#0f0;color:#000;border:none;padding:8px 20px;cursor:pointer;font-family:monospace;font-size:14px}
</style></head><body>
<canvas id="c" width="400" height="400"></canvas>
<div id="ui"><span>Score: <b id="score">0</b></span><span>Speed: <b id="speed">1</b></span></div>
<div id="gameover"><h2>GAME OVER</h2><p>Score: <span id="fscore"></span></p><button onclick="init()">Restart</button></div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d');
const SIZE=20,COLS=c.width/SIZE,ROWS=c.height/SIZE;
let snake,dir,food,score,speed,interval,gameOver;
function init(){snake=[{x:10,y:10}];dir={x:1,y:0};score=0;speed=1;gameOver=false;
  document.getElementById('gameover').style.display='none';
  document.getElementById('score').textContent='0';
  document.getElementById('speed').textContent='1';
  placeFood();if(interval)clearInterval(interval);interval=setInterval(tick,150)}
function placeFood(){food={x:Math.floor(Math.random()*COLS),y:Math.floor(Math.random()*ROWS)};
  if(snake.some(s=>s.x===food.x&&s.y===food.y))placeFood()}
function tick(){if(gameOver)return;
  const head={x:snake[0].x+dir.x,y:snake[0].y+dir.y};
  if(head.x<0||head.x>=COLS||head.y<0||head.y>=ROWS||snake.some(s=>s.x===head.x&&s.y===head.y)){endGame();return}
  snake.unshift(head);
  if(head.x===food.x&&head.y===food.y){score++;document.getElementById('score').textContent=score;
    if(score%5===0){speed++;document.getElementById('speed').textContent=speed;clearInterval(interval);interval=setInterval(tick,Math.max(50,150-speed*10))}
    placeFood()}else{snake.pop()}
  draw()}
function draw(){ctx.fillStyle='#111';ctx.fillRect(0,0,c.width,c.height);
  ctx.fillStyle='#0f0';snake.forEach(s=>ctx.fillRect(s.x*SIZE+1,s.y*SIZE+1,SIZE-2,SIZE-2));
  ctx.fillStyle='#f00';ctx.fillRect(food.x*SIZE+1,food.y*SIZE+1,SIZE-2,SIZE-2)}
function endGame(){gameOver=true;clearInterval(interval);
  document.getElementById('gameover').style.display='block';document.getElementById('fscore').textContent=score}
document.addEventListener('keydown',e=>{const k=e.key;
  if((k==='ArrowUp'||k==='w')&&dir.y!==1)dir={x:0,y:-1};
  else if((k==='ArrowDown'||k==='s')&&dir.y!==-1)dir={x:0,y:1};
  else if((k==='ArrowLeft'||k==='a')&&dir.x!==1)dir={x:-1,y:0};
  else if((k==='ArrowRight'||k==='d')&&dir.x!==-1)dir={x:1,y:0}});
init();
</script></body></html>
```

Here's Pong — two players, first to 5 wins:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Pong</title><style>
*{margin:0;padding:0}body{background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;color:#fff;font-family:monospace}
canvas{border:1px solid #333}
#info{margin-top:10px;font-size:13px;color:#888}
</style></head><body>
<canvas id="c" width="600" height="400"></canvas>
<div id="info">P1: W/S | P2: ↑/↓ | First to 5 wins</div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d');
const W=c.width,H=c.height,PAD_H=80,PAD_W=10,BALL_R=6;
let p1={y:H/2-PAD_H/2,score:0,dy:0},p2={y:H/2-PAD_H/2,score:0,dy:0};
let ball={x:W/2,y:H/2,dx:4,dy:3},running=true;
function reset(){ball={x:W/2,y:H/2,dx:(Math.random()>.5?4:-4),dy:(Math.random()*4-2)};}
function update(){if(!running)return;
  p1.y+=p1.dy;p2.y+=p2.dy;
  p1.y=Math.max(0,Math.min(H-PAD_H,p1.y));
  p2.y=Math.max(0,Math.min(H-PAD_H,p2.y));
  ball.x+=ball.dx;ball.y+=ball.dy;
  if(ball.y<=BALL_R||ball.y>=H-BALL_R)ball.dy*=-1;
  if(ball.x<=PAD_W+BALL_R&&ball.y>=p1.y&&ball.y<=p1.y+PAD_H){ball.dx=Math.abs(ball.dx)*1.05;ball.dy+=(ball.y-(p1.y+PAD_H/2))*0.1}
  if(ball.x>=W-PAD_W-BALL_R&&ball.y>=p2.y&&ball.y<=p2.y+PAD_H){ball.dx=-Math.abs(ball.dx)*1.05;ball.dy+=(ball.y-(p2.y+PAD_H/2))*0.1}
  if(ball.x<0){p2.score++;checkWin();reset()}
  if(ball.x>W){p1.score++;checkWin();reset()}}
function checkWin(){if(p1.score>=5||p2.score>=5){running=false;setTimeout(()=>{p1.score=0;p2.score=0;running=true;reset()},2000)}}
function draw(){ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);
  ctx.setLineDash([6,6]);ctx.strokeStyle='#333';ctx.beginPath();ctx.moveTo(W/2,0);ctx.lineTo(W/2,H);ctx.stroke();ctx.setLineDash([]);
  ctx.fillStyle='#fff';ctx.fillRect(0,p1.y,PAD_W,PAD_H);ctx.fillRect(W-PAD_W,p2.y,PAD_W,PAD_H);
  ctx.beginPath();ctx.arc(ball.x,ball.y,BALL_R,0,Math.PI*2);ctx.fill();
  ctx.font='48px monospace';ctx.textAlign='center';ctx.fillText(p1.score,W/4,60);ctx.fillText(p2.score,3*W/4,60);
  if(!running){ctx.font='24px monospace';ctx.fillStyle='#0f0';ctx.fillText((p1.score>=5?'P1':'P2')+' WINS!',W/2,H/2)}}
function loop(){update();draw();requestAnimationFrame(loop)}loop();
document.addEventListener('keydown',e=>{if(e.key==='w')p1.dy=-5;if(e.key==='s')p1.dy=5;if(e.key==='ArrowUp'){e.preventDefault();p2.dy=-5}if(e.key==='ArrowDown'){e.preventDefault();p2.dy=5}});
document.addEventListener('keyup',e=>{if(e.key==='w'||e.key==='s')p1.dy=0;if(e.key==='ArrowUp'||e.key==='ArrowDown')p2.dy=0});
</script></body></html>
```

Here's a clean todo app with persistence:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Todo</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a1a2e;color:#eee;font-family:system-ui;display:flex;justify-content:center;padding:40px}
.app{width:100%;max-width:500px}
h1{font-size:24px;margin-bottom:20px;color:#e94560}
.input-row{display:flex;gap:8px;margin-bottom:20px}
.input-row input{flex:1;padding:12px;background:#16213e;border:1px solid #0f3460;border-radius:8px;color:#eee;font-size:14px}
.input-row input:focus{outline:none;border-color:#e94560}
.input-row button{padding:12px 20px;background:#e94560;color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:600}
.input-row button:hover{background:#c73e54}
.todo{display:flex;align-items:center;gap:10px;padding:12px;background:#16213e;border-radius:8px;margin-bottom:8px;transition:opacity .3s}
.todo.done{opacity:.5}
.todo.done .text{text-decoration:line-through}
.todo input[type=checkbox]{width:18px;height:18px;accent-color:#e94560}
.todo .text{flex:1;font-size:14px}
.todo .del{background:none;border:none;color:#666;cursor:pointer;font-size:18px;padding:4px 8px;border-radius:4px}
.todo .del:hover{color:#e94560;background:rgba(233,69,96,.1)}
.empty{text-align:center;color:#555;padding:40px;font-size:14px}
.count{font-size:12px;color:#555;margin-top:12px}
</style></head><body>
<div class="app">
<h1>Todos</h1>
<div class="input-row"><input id="inp" placeholder="What needs to be done?" onkeydown="if(event.key==='Enter')add()"><button onclick="add()">Add</button></div>
<div id="list"></div>
<div class="count" id="count"></div>
</div>
<script>
let todos=JSON.parse(localStorage.getItem('todos')||'[]');
function save(){localStorage.setItem('todos',JSON.stringify(todos));render()}
function add(){const v=document.getElementById('inp').value.trim();if(!v)return;
  todos.push({id:Date.now(),text:v,done:false});document.getElementById('inp').value='';save()}
function toggle(id){const t=todos.find(x=>x.id===id);if(t)t.done=!t.done;save()}
function del(id){todos=todos.filter(x=>x.id!==id);save()}
function render(){const list=document.getElementById('list');
  if(!todos.length){list.innerHTML='<div class="empty">No todos yet. Add one above.</div>';document.getElementById('count').textContent='';return}
  list.innerHTML=todos.map(t=>`<div class="todo${t.done?' done':''}">
    <input type="checkbox" ${t.done?'checked':''} onchange="toggle(${t.id})">
    <span class="text">${t.text}</span>
    <button class="del" onclick="del(${t.id})">×</button></div>`).join('');
  const left=todos.filter(t=>!t.done).length;
  document.getElementById('count').textContent=`${left} item${left!==1?'s':''} left`}
render();
</script></body></html>
```

Here's a Pomodoro timer with audio alert:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Pomodoro</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a0a2e;color:#fff;font-family:system-ui;display:flex;align-items:center;justify-content:center;height:100vh}
.app{text-align:center}
.timer{font-size:80px;font-weight:200;font-family:monospace;margin:30px 0;color:#f0e68c}
.mode{font-size:14px;text-transform:uppercase;letter-spacing:3px;color:#888;margin-bottom:10px}
.btns{display:flex;gap:12px;justify-content:center;margin-top:20px}
.btns button{padding:12px 28px;border:none;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;transition:transform .1s}
.btns button:active{transform:scale(.95)}
#startBtn{background:#4ade80;color:#000}
#resetBtn{background:#333;color:#fff}
.modes{display:flex;gap:8px;justify-content:center;margin-top:20px}
.modes button{padding:8px 16px;border:1px solid #333;background:transparent;color:#888;border-radius:20px;cursor:pointer;font-size:12px}
.modes button.active{border-color:#f0e68c;color:#f0e68c}
.cycles{margin-top:16px;font-size:12px;color:#555}
</style></head><body>
<div class="app">
<div class="mode" id="modeLabel">Focus</div>
<div class="timer" id="timer">25:00</div>
<div class="btns"><button id="startBtn" onclick="toggleTimer()">Start</button><button id="resetBtn" onclick="resetTimer()">Reset</button></div>
<div class="modes"><button class="active" onclick="setMode(25,'Focus',this)">Focus</button><button onclick="setMode(5,'Break',this)">Short Break</button><button onclick="setMode(15,'Long Break',this)">Long Break</button></div>
<div class="cycles" id="cycles">Completed: 0</div>
</div>
<script>
let duration=25*60,remaining=duration,running=false,interval=null,cycles=0;
const audioCtx=new(window.AudioContext||window.webkitAudioContext)();
function beep(){const o=audioCtx.createOscillator(),g=audioCtx.createGain();
  o.connect(g);g.connect(audioCtx.destination);o.frequency.value=800;o.type='sine';
  g.gain.setValueAtTime(0.3,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(0.01,audioCtx.currentTime+0.5);
  o.start();o.stop(audioCtx.currentTime+0.5)}
function display(){const m=Math.floor(remaining/60),s=remaining%60;
  document.getElementById('timer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function toggleTimer(){if(running){clearInterval(interval);running=false;document.getElementById('startBtn').textContent='Start'}
  else{running=true;document.getElementById('startBtn').textContent='Pause';
    interval=setInterval(()=>{remaining--;display();
      if(remaining<=0){clearInterval(interval);running=false;beep();beep();
        document.getElementById('startBtn').textContent='Start';
        if(document.getElementById('modeLabel').textContent==='Focus'){cycles++;document.getElementById('cycles').textContent='Completed: '+cycles}
      }},1000)}}
function resetTimer(){clearInterval(interval);running=false;remaining=duration;display();document.getElementById('startBtn').textContent='Start'}
function setMode(min,label,el){duration=min*60;remaining=duration;running=false;clearInterval(interval);
  document.getElementById('startBtn').textContent='Start';document.getElementById('modeLabel').textContent=label;display();
  document.querySelectorAll('.modes button').forEach(b=>b.classList.remove('active'));el.classList.add('active')}
display();
</script></body></html>
```

Here's a memory card game — match all pairs:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Memory</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0d1117;color:#fff;font-family:system-ui;display:flex;flex-direction:column;align-items:center;padding:40px}
h1{margin-bottom:8px;font-size:20px}
#stats{font-size:13px;color:#888;margin-bottom:20px}
.grid{display:grid;grid-template-columns:repeat(4,90px);gap:10px}
.card{width:90px;height:90px;perspective:600px;cursor:pointer}
.card-inner{width:100%;height:100%;position:relative;transform-style:preserve-3d;transition:transform .4s}
.card.flipped .card-inner,.card.matched .card-inner{transform:rotateY(180deg)}
.card-front,.card-back{position:absolute;width:100%;height:100%;backface-visibility:hidden;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:32px}
.card-front{background:#21262d;border:2px solid #30363d}
.card-back{background:#161b22;border:2px solid #58a6ff;transform:rotateY(180deg)}
.card.matched .card-back{border-color:#3fb950;background:#0d2818}
#win{display:none;margin-top:20px;text-align:center}
#win button{margin-top:10px;padding:10px 24px;background:#58a6ff;border:none;color:#000;border-radius:8px;cursor:pointer;font-weight:600}
</style></head><body>
<h1>Memory Match</h1>
<div id="stats">Moves: <span id="moves">0</span> | Pairs: <span id="pairs">0</span>/8</div>
<div class="grid" id="grid"></div>
<div id="win"><h2>You Win!</h2><p id="winMsg"></p><button onclick="init()">Play Again</button></div>
<script>
const EMOJIS=['🎮','🚀','🎨','🔥','💎','🌙','⚡','🎵'];
let cards,flipped=[],locked=false,moves=0,matched=0;
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function init(){const pairs=[...EMOJIS,...EMOJIS];shuffle(pairs);moves=0;matched=0;flipped=[];locked=false;
  document.getElementById('moves').textContent='0';document.getElementById('pairs').textContent='0';
  document.getElementById('win').style.display='none';
  const grid=document.getElementById('grid');grid.innerHTML='';
  pairs.forEach((emoji,i)=>{const card=document.createElement('div');card.className='card';card.dataset.idx=i;card.dataset.emoji=emoji;
    card.innerHTML=`<div class="card-inner"><div class="card-front">?</div><div class="card-back">${emoji}</div></div>`;
    card.onclick=()=>flip(card);grid.appendChild(card)})}
function flip(card){if(locked||card.classList.contains('flipped')||card.classList.contains('matched'))return;
  card.classList.add('flipped');flipped.push(card);
  if(flipped.length===2){moves++;document.getElementById('moves').textContent=moves;locked=true;
    if(flipped[0].dataset.emoji===flipped[1].dataset.emoji){flipped.forEach(c=>c.classList.add('matched'));matched++;
      document.getElementById('pairs').textContent=matched;flipped=[];locked=false;
      if(matched===8){document.getElementById('win').style.display='block';document.getElementById('winMsg').textContent=`Completed in ${moves} moves!`}}
    else{setTimeout(()=>{flipped.forEach(c=>c.classList.remove('flipped'));flipped=[];locked=false},800)}}}
init();
</script></body></html>
```

Here's Tic-tac-toe with minimax AI — unbeatable:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Tic Tac Toe</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#111;color:#fff;font-family:system-ui;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh}
h1{font-size:20px;margin-bottom:16px}
.board{display:grid;grid-template-columns:repeat(3,100px);gap:4px}
.cell{width:100px;height:100px;background:#222;border:none;color:#fff;font-size:40px;cursor:pointer;transition:background .2s}
.cell:hover{background:#333}
.cell.x{color:#58a6ff}.cell.o{color:#f97316}
#msg{margin-top:16px;font-size:14px;height:20px}
#restart{margin-top:12px;padding:10px 20px;background:#333;color:#fff;border:none;border-radius:6px;cursor:pointer;display:none}
#restart:hover{background:#444}
</style></head><body>
<h1>Tic Tac Toe vs AI</h1>
<div class="board" id="board"></div>
<div id="msg">Your turn (X)</div>
<button id="restart" onclick="init()">Play Again</button>
<script>
let board,human='X',ai='O',gameOver;
function init(){board=Array(9).fill('');gameOver=false;document.getElementById('msg').textContent='Your turn (X)';
  document.getElementById('restart').style.display='none';render()}
function render(){const el=document.getElementById('board');el.innerHTML='';
  board.forEach((v,i)=>{const btn=document.createElement('button');btn.className='cell'+(v===' '?'':' '+v.toLowerCase());
    btn.textContent=v;btn.onclick=()=>play(i);el.appendChild(btn)})}
function play(i){if(board[i]||gameOver)return;board[i]=human;if(check(human)){end('You win!');return}
  if(board.every(c=>c)){end('Draw!');return}
  const m=minimax(board,ai);board[m.idx]=ai;if(check(ai)){end('AI wins!');return}
  if(board.every(c=>c)){end('Draw!');return}render()}
function end(msg){gameOver=true;render();document.getElementById('msg').textContent=msg;document.getElementById('restart').style.display='block'}
function check(p){const w=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
  return w.some(l=>l.every(i=>board[i]===p))}
function minimax(b,player){if(check(human))return{score:-10};if(check(ai))return{score:10};if(b.every(c=>c))return{score:0};
  const moves=[];b.forEach((v,i)=>{if(!v){const nb=[...b];nb[i]=player;
    const result=minimax(nb,player===ai?human:ai);moves.push({idx:i,score:result.score})}});
  return player===ai?moves.reduce((a,b)=>b.score>a.score?b:a):moves.reduce((a,b)=>b.score<a.score?b:a)}
init();
</script></body></html>
```

Here's a scientific calculator with full keyboard support:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Calculator</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0f0f0f;display:flex;align-items:center;justify-content:center;height:100vh;font-family:system-ui}
.calc{background:#1a1a1a;border-radius:16px;padding:20px;width:320px;box-shadow:0 20px 60px rgba(0,0,0,.5)}
.display{background:#0a0a0a;border-radius:10px;padding:16px;margin-bottom:16px;text-align:right;min-height:70px;display:flex;flex-direction:column;justify-content:flex-end}
.expr{font-size:13px;color:#666;min-height:18px}
.result{font-size:32px;color:#fff;font-weight:300;overflow:hidden;text-overflow:ellipsis}
.btns{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.btn{padding:18px;border:none;border-radius:10px;font-size:18px;cursor:pointer;transition:all .1s;font-family:system-ui}
.btn:active{transform:scale(.95)}
.btn-num{background:#2a2a2a;color:#fff}
.btn-num:hover{background:#3a3a3a}
.btn-op{background:#333;color:#f97316}
.btn-op:hover{background:#444}
.btn-fn{background:#222;color:#888}
.btn-fn:hover{background:#333}
.btn-eq{background:#f97316;color:#fff}
.btn-eq:hover{background:#e86305}
.btn-clear{background:#c0392b;color:#fff}
.btn-clear:hover{background:#e74c3c}
</style></head><body>
<div class="calc">
<div class="display"><div class="expr" id="expr"></div><div class="result" id="result">0</div></div>
<div class="btns">
<button class="btn btn-clear" onclick="clear_()">C</button><button class="btn btn-fn" onclick="input('(')">(</button><button class="btn btn-fn" onclick="input(')')">)</button><button class="btn btn-op" onclick="input('/')">/</button>
<button class="btn btn-num" onclick="input('7')">7</button><button class="btn btn-num" onclick="input('8')">8</button><button class="btn btn-num" onclick="input('9')">9</button><button class="btn btn-op" onclick="input('*')">×</button>
<button class="btn btn-num" onclick="input('4')">4</button><button class="btn btn-num" onclick="input('5')">5</button><button class="btn btn-num" onclick="input('6')">6</button><button class="btn btn-op" onclick="input('-')">−</button>
<button class="btn btn-num" onclick="input('1')">1</button><button class="btn btn-num" onclick="input('2')">2</button><button class="btn btn-num" onclick="input('3')">3</button><button class="btn btn-op" onclick="input('+')">+</button>
<button class="btn btn-num" onclick="input('0')" style="grid-column:span 2">0</button><button class="btn btn-num" onclick="input('.')">.</button><button class="btn btn-eq" onclick="calc()">=</button>
</div></div>
<script>
let expr='';
function input(v){expr+=v;document.getElementById('expr').textContent=expr;try{document.getElementById('result').textContent=eval(expr)||'0'}catch(e){}}
function calc(){try{const r=eval(expr);document.getElementById('result').textContent=r;expr=String(r)}catch(e){document.getElementById('result').textContent='Error';expr=''}}
function clear_(){expr='';document.getElementById('expr').textContent='';document.getElementById('result').textContent='0'}
document.addEventListener('keydown',e=>{const k=e.key;if('0123456789.+-*/()'.includes(k))input(k);
  else if(k==='Enter')calc();else if(k==='Escape'||k==='c')clear_();else if(k==='Backspace'){expr=expr.slice(0,-1);document.getElementById('expr').textContent=expr}});
</script></body></html>
```

Here's a split-pane Markdown editor with live preview:

