<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Type Test</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0f172a;color:#e2e8f0;font-family:system-ui;display:flex;align-items:center;justify-content:center;height:100vh}
