function render(){const el=document.getElementById('habits');
  el.innerHTML=habits.map(h=>{const streak=getStreak(h.days);
    return`<div class="habit"><div class="habit-header"><span class="habit-name">${h.name}</span><span class="streak">${streak>0?streak+' day streak':''}${'🔥'.repeat(Math.min(streak,7))}</span><button class="del" onclick="del(${h.id})">×</button></div><div class="days">${DAYS.map((d,i)=>`<div class="day${h.days[i]?' done':''}" onclick="toggle(${h.id},${i})">${d}</div>`).join('')}</div></div>`}).join('')}
