Here's the complete REST API design for a blog platform:

## Endpoints

| Method | Path | Description |
|--------|------|-------------|
| GET | /api/posts | List posts (paginated) |
| GET | /api/posts/:id | Get single post |
| POST | /api/posts | Create post (auth required) |
| PUT | /api/posts/:id | Update post (owner only) |
| DELETE | /api/posts/:id | Delete post (owner only) |
| GET | /api/posts/:id/comments | List comments on post |
| POST | /api/posts/:id/comments | Add comment (auth required) |
| POST | /api/auth/register | Create account |
| POST | /api/auth/login | Get JWT token |
| GET | /api/users/:id | Public profile |

## Data Models

```javascript
// User
{ id, username, email, passwordHash, avatar, bio, createdAt }

// Post
{ id, title, slug, content, excerpt, coverImage, authorId, tags[], status: 'draft'|'published', publishedAt, createdAt, updatedAt }

// Comment
{ id, postId, authorId, content, createdAt }
```

## Express Implementation

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();
app.use(express.json());

const SECRET = process.env.JWT_SECRET;

function auth(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });
  try { req.user = jwt.verify(token, SECRET); next(); }
  catch { res.status(401).json({ error: 'Invalid token' }) }
}

// Posts
app.get('/api/posts', async (req, res) => {
  const { page = 1, limit = 10, tag } = req.query;
  const offset = (page - 1) * limit;
  const posts = await db.query(
    `SELECT p.*, u.username as author FROM posts p JOIN users u ON p.author_id = u.id
     WHERE status = 'published' ${tag ? 'AND $3 = ANY(tags)' : ''}
     ORDER BY published_at DESC LIMIT $1 OFFSET $2`,
    tag ? [limit, offset, tag] : [limit, offset]
  );
  res.json({ posts: posts.rows, page: +page, hasMore: posts.rows.length === +limit });
});

app.post('/api/posts', auth, async (req, res) => {
  const { title, content, tags, status } = req.body;
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const excerpt = content.slice(0, 160);
  const post = await db.query(
    'INSERT INTO posts (title, slug, content, excerpt, tags, status, author_id, published_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',
    [title, slug, content, excerpt, tags, status, req.user.id, status === 'published' ? new Date() : null]
  );
  res.status(201).json(post.rows[0]);
});

// Auth
app.post('/api/auth/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await db.query('SELECT * FROM users WHERE email = $1', [email]);
  if (!user.rows[0] || !await bcrypt.compare(password, user.rows[0].password_hash))
    return res.status(401).json({ error: 'Invalid credentials' });
  const token = jwt.sign({ id: user.rows[0].id, username: user.rows[0].username }, SECRET, { expiresIn: '7d' });
  res.json({ token, user: { id: user.rows[0].id, username: user.rows[0].username } });
});

app.listen(3000);
```

## Response Format
```json
{
  "posts": [{"id": 1, "title": "...", "author": "om", ...}],
  "page": 1,
  "hasMore": true
}
```

Error responses always: `{"error": "message"}` with appropriate HTTP status codes.

Here's an endless runner with obstacles and score:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Runner</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a1a2e;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:monospace;color:#fff}
canvas{border:2px solid #e94560;background:#16213e}
#ui{margin-top:10px;font-size:14px;display:flex;gap:20px}
#msg{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:18px;display:none;background:rgba(0,0,0,.8);padding:20px 40px;border-radius:10px;text-align:center}
#msg button{margin-top:10px;padding:8px 20px;background:#e94560;border:none;color:#fff;border-radius:4px;cursor:pointer}
</style></head><body>
<canvas id="c" width="600" height="200"></canvas>
<div id="ui">Score: <b id="score">0</b> | High: <b id="high">0</b></div>
<div id="msg"><div>Game Over!</div><div id="finalScore"></div><button onclick="init()">Restart</button></div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d');
const W=c.width,H=c.height,GROUND=H-30,PLAYER_W=30,PLAYER_H=40;
let player,obstacles,score,speed,gameOver,high=+localStorage.getItem('runner_high')||0,jumpVel;
document.getElementById('high').textContent=high;
function init(){player={x:60,y:GROUND-PLAYER_H,vy:0,jumping:false};obstacles=[];score=0;speed=4;gameOver=false;jumpVel=-12;
  document.getElementById('msg').style.display='none';loop()}
function jump(){if(!player.jumping){player.vy=jumpVel;player.jumping=true}}
function update(){if(gameOver)return;
  player.vy+=0.7;player.y+=player.vy;
  if(player.y>=GROUND-PLAYER_H){player.y=GROUND-PLAYER_H;player.vy=0;player.jumping=false}
  if(Math.random()<0.02)obstacles.push({x:W,w:20+Math.random()*20,h:30+Math.random()*20});
  obstacles.forEach(o=>o.x-=speed);
  obstacles=obstacles.filter(o=>o.x+o.w>0);
  for(const o of obstacles){if(player.x+PLAYER_W>o.x&&player.x<o.x+o.w&&player.y+PLAYER_H>GROUND-o.h){endGame();return}}
  score++;speed=4+score*0.005;document.getElementById('score').textContent=Math.floor(score/10)}
function draw(){ctx.fillStyle='#16213e';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#0f3460';ctx.fillRect(0,GROUND,W,30);
  ctx.fillStyle='#e94560';ctx.fillRect(player.x,player.y,PLAYER_W,PLAYER_H);
  ctx.fillStyle='#f97316';obstacles.forEach(o=>ctx.fillRect(o.x,GROUND-o.h,o.w,o.h))}
function endGame(){gameOver=true;const s=Math.floor(score/10);if(s>high){high=s;localStorage.setItem('runner_high',high);document.getElementById('high').textContent=high}
  document.getElementById('finalScore').textContent='Score: '+s;
  document.getElementById('msg').style.display='block'}
function loop(){if(!gameOver){update();draw();requestAnimationFrame(loop)}}
document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();if(gameOver)init();else jump()}});
c.addEventListener('touchstart',()=>{if(gameOver)init();else jump()});
init();
</script></body></html>
