<script>
const audioCtx=new(window.AudioContext||window.webkitAudioContext)();
const FREQS=[261,329,392,523];
let sequence=[],playerPos=0,playing=false,score=0;
function tone(idx){const o=audioCtx.createOscillator(),g=audioCtx.createGain();
  o.connect(g);g.connect(audioCtx.destination);o.frequency.value=FREQS[idx];o.type='sine';
  g.gain.setValueAtTime(.3,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.01,audioCtx.currentTime+.3);
  o.start();o.stop(audioCtx.currentTime+.3)}
function light(idx,dur=300){const el=document.getElementById('p'+idx);el.classList.add('lit');tone(idx);setTimeout(()=>el.classList.remove('lit'),dur)}
function playSequence(){playing=true;let i=0;const iv=setInterval(()=>{if(i>=sequence.length){clearInterval(iv);playing=false;playerPos=0;return}light(sequence[i]);i++},600)}
function addRound(){sequence.push(Math.floor(Math.random()*4));playSequence()}
function press(idx){if(playing)return;
  light(idx,200);
  if(idx!==sequence[playerPos]){document.getElementById('info').textContent='Wrong! Game over. Score: '+score;sequence=[];return}
  playerPos++;
  if(playerPos===sequence.length){score++;document.getElementById('score').textContent='Score: '+score;
    document.getElementById('info').textContent='Correct! Next round...';setTimeout(addRound,1000)}}
function startGame(){sequence=[];score=0;document.getElementById('score').textContent='Score: 0';
  document.getElementById('info').textContent='Watch the pattern...';setTimeout(addRound,500)}
</script></body></html>
